import SwiftUI

/// The Sbu design tokens as typed values.
///
/// Token names match `Design/tokens.json`, camel-cased: `surface-raised` is `surfaceRaised`,
/// `space-4` is `space4`. Colors, spacing, radii and strokes are generated by
/// `Tools/sync_tokens.py`; typography lives in `SbuTheme+Typography.swift`.
public enum SbuTheme {
    /// The bundle holding SbuKit's assets and strings.
    static let bundle = Bundle.module

    /// Text and glyphs on top of `accentLevel`.
    ///
    /// The design system makes one exception to `onAccent`: the yellow of Sbu Level takes
    /// `ink` in its light value (#14181f), never white.
    public static let onAccentLevel = Color(red: 0x14 / 255, green: 0x18 / 255, blue: 0x1F / 255)
}
